/**
 * @brief Parses one expression starting at the current token.
 *
 * Stops at the first token that cannot continue the expression and leaves it
 * as the current token (it is not consumed). Throws E_SYNTAX_ERROR when no
 * valid expression starts at the current token.
 *
 * @param[in,out] ctx Non-null pointer to an initialized context
 * @param[in,out] parser Parser state
 * @return The expression's AST subtree; the caller attaches it to its parent
 */
AstNode* expr_parse(Ctx* ctx, Parser* parser);

